# bash completion for s3-archive
# Generated by `make completions` from the argparse parser; do not edit.

_s3_archive() {
    local cur=${COMP_WORDS[COMP_CWORD]} prev=${COMP_WORDS[COMP_CWORD-1]}
    local cmd="" i

    # A value-taking option's argument is free text: offer nothing.
    case $prev in
        --profile) return 0 ;;
    esac

    # The subcommand, if one was typed, skipping option values.
    for ((i = 1; i < COMP_CWORD; i++)); do
        case ${COMP_WORDS[i]} in
            --profile) ((i++)) ;;
            extract|create|ls|config) cmd=${COMP_WORDS[i]}; break ;;
        esac
    done

    local words
    case $cmd in
        "") words="-h --help --version -v --verbose" ;;
        extract) words="-h --help --dry-run --fix-unsafe-paths --resume" ;;
        create) words="-h --help --dry-run" ;;
        ls) words="-h --help --fix-unsafe-paths" ;;
        config) words="-h --help --profile" ;;
    esac
    if [[ -z $cmd && $cur != -* ]]; then
        words="extract create ls config"
    fi
    mapfile -t COMPREPLY < <(compgen -W "$words" -- "$cur")
}

complete -F _s3_archive s3-archive
